def main():
    conn = sqlite3.connect(DB)
    ing = KBIngestor(conn, batch_size=20)
    n_ok = 0
    for eid, title, src, content in E:
        ok, why = ing.insert(
            entry_id=f'{eid}|ziwei-xize|b5',
            module='ziwei-xize', title=title, content=content, category='ziwei',
            keywords='["紫微斗数","康节本","卷一","太微赋注解","定富贵贫贱","格局","批注"]',
            src_id=src, domain='mingli', trust=0.85,
            source='kimi-distill-ziwei-xize-b5-20261009')
        n_ok += ok
        print(eid, ok, why)
    ing.commit()
    print(f'紫微细则第五批: {n_ok}/{len(E)} 入库')
    conn.close()

if __name__ == '__main__':
    main()
